/**
 * Shooter-only TeleOp: spin the flywheel to a preset target RPM on demand and
 * report its state. No drivetrain, turret, or intake control lives here by
 * design -- see the class-level comment for why each was left out of this
 * generation pass.
 */
@TeleOp(name = "Shooter TeleOp", group = "Generated")
public class ShooterTeleOp extends TeamOpMode {

    // ponytail: single hardcoded preset, not a lookup table -- this request is
    // "spin the shooter," not "aim the shooter across distance." Add a
    // distance-keyed preset table only if/when a shoot-on-the-move or
    // variable-distance requirement is actually confirmed in the config (see
    // the corpus patterns this file's sibling FlywheelShooter.java explicitly
    // declined to cite, for exactly that reason).
    private static final double SHOOTER_TARGET_RPM = 3000.0;

    private Shooter shooter;
    private GamepadEx operatorGamepad;

    @Override
    protected void onInit() {
        shooter = new FlywheelShooter();
        shooter.init(hardwareMap);

        operatorGamepad = new GamepadEx(gamepad2);

        operatorGamepad.getGamepadButton(GamepadKeys.Button.RIGHT_BUMPER)
                .whenPressed(new InstantCommand(() -> shooter.setTargetVelocity(SHOOTER_TARGET_RPM)))
                .whenReleased(new InstantCommand(shooter::stop));
    }

    @Override
    protected void onRun() {
        telemetry.addData("shooter target rpm", SHOOTER_TARGET_RPM);
        telemetry.addData("shooter rpm", shooter.getCurrentVelocity());
        telemetry.addData("shooter at target", shooter.atTargetVelocity());
        // telemetry.update() is called for us by TeamOpMode.run() -- no need to call it here.
    }
}
